// Import required packages
const express = require('express');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const dotenv = require('dotenv');
const cors = require('cors');
const bodyParser = require('body-parser');

// Import User model and validation utilities
const User = require('./models/User');
const { isValidEmail, isStrongPassword } = require('./utils/validation');

// Load environment variables from .env file
dotenv.config();

// Connect to MongoDB database
mongoose.connect(process.env.MONGODB_URI, { useNewUrlParser: true, useUnifiedTopology: true, useCreateIndex: true });

// Initialize Express app and configure middleware
const app = express();
app.use(cors());
app.use(bodyParser.json());

// Generate JWT token for a user
function generateToken(user) {
  return jwt.sign({ id: user._id }, process.env.SECRET_KEY, { expiresIn: '24h' });
}

// Register endpoint
app.post('/register', async (req, res) => {
  const { email, password } = req.body;

  if (!isValidEmail(email)) {
    return res.status(400).json({ message: 'Invalid email format' });
  }

  if (!isStrongPassword(password)) {
    return res.status(400).json({ message: 'Weak password. Must have at least one uppercase letter, one lowercase letter, one number, one special character and be at least 8 characters long.' });
  }

  const existingUser = await User.findOne({ email });

  if (existingUser) {
    return res.status(409).json({ message: 'Email already in use' });
  }

  const hashedPassword = await bcrypt.hash(password, 10);
  const user = new User({ email, password: hashedPassword });
  await user.save();

  res.status(201).json({ message: 'User registered successfully', user });
});

// Login endpoint
app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  const user = await User.findOne({ email });

  if (!user || !(await bcrypt.compare(password, user.password))) {
    return res.status(401).json({ message: 'Invalid email or password' });
  }

  const token = generateToken(user);

  res.json({ message: 'Logged in successfully', token });
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
